customElements.define('basic-search',class extends HTMLElement{constructor(){super();this.ACTIVE_CLASS='active';this.HIDDEN_CLASS='is-hidden';this.ALL_KEYWORD='all';this.SEARCH_INPUT='[data-search-input]';this.CLEAR_INPUT='[data-clear-input]';this.SELECT_INPUT='[data-search-select]';this.FILTER_TOGGLE='[data-search-filter]';this.CLEAR_FILTERS='[data-clear-filters]';this.DATA_FILTER_FOR='data-filter-for';this.SEARCH_ITEM='[data-search-item]';this.SEARCH_TEXT='[data-search-text]';this.SHOW_MORE='[data-show-more]';this.activeFilters=[];this.hasSearchInput=!1;this.hasSearchSelect=!1;this.hasFilters=!1;this.hasPagination=!1;this.resultsCount=0;this.currentVisibleItems=0}
connectedCallback(){this.setupComponent()}
setupComponent(){this.searchContainerSelector=this.getAttribute('search-container');this.summaryTextSelector=this.getAttribute('summary-text');this.paginateSummarySelector=this.getAttribute('paginate-summary')
this.noResultsSelector=this.getAttribute('no-results');this.searchSelectorDataTarget=this.getAttribute('search-selector-data');this.searchFilterDataTarget=this.getAttribute('search-filter-data');this.paginateControlSelector=this.getAttribute('paginate-controls');this.resultsPerPage=parseInt(this.getAttribute('results-per-page'),10);this.currentVisibleItems=this.resultsPerPage||0;this.searchInputElement=this.querySelector(this.SEARCH_INPUT);this.clearInputBtnElement=this.querySelector(this.CLEAR_INPUT);this.searchSelectElement=this.querySelector(this.SELECT_INPUT);this.searchFilterElements=Array.from(this.querySelectorAll(this.FILTER_TOGGLE));this.clearFiltersBtnElement=this.querySelector(this.CLEAR_FILTERS);this.summaryTextElement=document.querySelector(this.summaryTextSelector);this.paginateSummaryElement=document.querySelector(this.paginateSummarySelector);this.noResultsElement=document.querySelector(this.noResultsSelector);this.searchContainerElement=document.querySelector(this.searchContainerSelector);this.paginateControls=document.querySelector(this.paginateControlSelector);if(this.paginateControls)
this.showMoreBtnElement=this.paginateControls.querySelector(this.SHOW_MORE);this.hasSearchInput=!!this.searchInputElement;this.hasSearchSelect=!!this.searchSelectElement;this.hasFilters=this.searchFilterElements.length>0;this.hasPagination=!!this.paginateControls;if(this.hasSearchInput){this.searchInputElement.addEventListener('input',()=>{this.executeSearch()});if(this.clearInputBtnElement){this.clearInputBtnElement.addEventListener('click',()=>{this.clearSearchInput()})}}
if(this.hasSearchSelect){this.searchSelectElement.addEventListener('change',()=>{this.executeSearch()})}
if(this.hasFilters){this.searchFilterElements.forEach(toggle=>{toggle.addEventListener('click',()=>{this.updateActiveFilters();this.executeSearch()})});if(this.clearFiltersBtnElement){this.clearFiltersBtnElement.addEventListener('click',()=>{this.clearAllFilters()})}}
if(this.noResultsElement)
this.noResultsElement.style.display='none';if(this.hasPagination){this.showMoreBtnElement.addEventListener('click',()=>{this.currentVisibleItems+=this.resultsPerPage;if(this.currentVisibleItems>=this.resultsCount)
this.currentVisibleItems=this.resultsCount;this.updatePagination()})}
this.executeSearch()}
clearSearchInput(){this.searchInputElement.value='';this.executeSearch()}
updateActiveFilters(){this.activeFilters=[];if(this.hasFilters){this.searchFilterElements.forEach(toggle=>{if(toggle.classList.contains(this.ACTIVE_CLASS)&&toggle.hasAttribute(this.DATA_FILTER_FOR)){this.activeFilters.push(toggle.dataset.filterFor.toLowerCase().trim())}})}}
clearAllFilters(){if(this.hasFilters){this.searchFilterElements.forEach(toggle=>{toggle.classList.remove(this.ACTIVE_CLASS)})}
this.updateActiveFilters();this.executeSearch()}
executeSearch(){const searchText=this.hasSearchInput?this.searchInputElement.value.toLowerCase().trim():'';const currentSelection=this.hasSearchSelect?this.searchSelectElement.value.toLowerCase().trim():this.ALL_KEYWORD;const targetContainer=this.searchContainerElement||this;const searchItems=Array.from(targetContainer.querySelectorAll(this.SEARCH_ITEM));this.resultsCount=0;this.currentVisibleItems=this.resultsPerPage;searchItems.forEach(item=>{const searchTextElement=item.querySelector(this.SEARCH_TEXT);const itemName=searchTextElement?searchTextElement.textContent.toLowerCase().trim():item.textContent;const hasInputMatch=!this.hasSearchInput||searchText===''||itemName.includes(searchText);const itemSelectDataAttribute=this.searchSelectorDataTarget?item.getAttribute(this.searchSelectorDataTarget):null;const itemSelection=itemSelectDataAttribute?itemSelectDataAttribute.toLowerCase().trim():'';const hasSelectMatch=!this.hasSearchSelect||currentSelection===this.ALL_KEYWORD||itemSelection.includes(currentSelection);const itemTagDataAttribute=this.searchFilterDataTarget?item.getAttribute(this.searchFilterDataTarget):null;const itemTags=itemTagDataAttribute?itemTagDataAttribute.split(",").map(tag=>tag.toLowerCase().trim()):[];const hasTagMatch=!this.hasFilters||this.activeFilters.length===0||this.activeFilters.some(tag=>itemTags.includes(tag));if(hasInputMatch&&hasSelectMatch&&hasTagMatch){item.style.display='';item.classList.remove(this.HIDDEN_CLASS);this.resultsCount++}else{item.style.display='none';item.classList.add(this.HIDDEN_CLASS)}});this.resultsFeedbackCheck();this.updateSummaryText();this.updatePagination()}
resetSearch(){this.searchInputElement.value='';if(this.hasFilters){this.searchFilterElements.forEach(toggle=>{toggle.classList.remove(this.ACTIVE_CLASS)})}
this.updateActiveFilters();this.executeSearch()}
updatePagination(){if(!this.hasPagination)
return;const searchItems=Array.from(this.searchContainerElement.querySelectorAll(`${this.SEARCH_ITEM}:not(.${this.HIDDEN_CLASS})`));searchItems.forEach((item,index)=>{if(index<this.currentVisibleItems){item.style.display=''}else{item.style.display='none'}});if(this.resultsCount===0||this.currentVisibleItems===this.resultsCount||this.resultsCount<this.resultsPerPage){this.paginateControls.classList.add('hide');this.showMoreBtnElement.disabled=!0}else{this.paginateControls.classList.remove('hide');this.showMoreBtnElement.disabled=!1}
this.updateSummaryText()}
resultsFeedbackCheck(){if(!this.noResultsElement)
return;if(this.resultsCount===0){this.noResultsElement.style.display='';if(this.hasPagination){this.paginateControls.classList.add('hide');this.showMoreBtnElement.disabled=!0}}else{this.noResultsElement.style.display='none';if(this.hasPagination){this.paginateControls.classList.remove('hide');this.showMoreBtnElement.disabled=!1}}}
updateSummaryText(){if(!this.summaryTextElement)
return;if(this.resultsCount===0){this.summaryTextElement.textContent='No Results';if(this.hasPagination)
this.updatePaginationSummary();return}
if(this.hasPagination){const minVisible=this.currentVisibleItems-this.currentVisibleItems+1;const maxVisible=(this.currentVisibleItems>this.resultsCount)?this.resultsCount:this.currentVisibleItems;this.summaryTextElement.textContent=`Showing (${minVisible} - ${maxVisible}) of (${this.resultsCount}) results`;this.updatePaginationSummary()}else{this.summaryTextElement.textContent=`Showing ${this.resultsCount} Results`}}
updatePaginationSummary(){if(!this.paginateSummaryElement)
return;if(this.resultsCount===0){this.paginateSummaryElement.textContent='';return}
const itemsRemaining=this.resultsCount-this.currentVisibleItems;const itemPlural=(itemsRemaining>1)?"items":"item";if(itemsRemaining>0){this.paginateSummaryElement.textContent=`(${itemsRemaining}) ${itemPlural} remaining`}else{this.paginateSummaryElement.textContent=''}}})